import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// Runtime support for code generated by protoc-gen-protomorphic-kotlin: typed extension access on top of
// the Wire runtime, which does the binary encoding.
plugins {
    alias(libs.plugins.kotlinMultiplatform)
    alias(libs.plugins.androidMultiplatformLibrary)
    alias(libs.plugins.mavenPublish)
}

kotlin {
    jvm()
    iosArm64()
    iosSimulatorArm64()
    android {
        namespace = "studio.dabble.protomorphic.runtime"
        compileSdk {
            version = release(37)
        }
        minSdk = 26
        compilerOptions {
            jvmTarget = JvmTarget.JVM_17
        }
    }

    sourceSets {
        commonMain.dependencies {
            api(libs.wire.runtime)
        }
    }
}

mavenPublishing {
    pom {
        name = "ProtoMorphic runtime"
        description = "Runtime for Kotlin generated by ProtoMorphic: typed protobuf extensions and interfaces on the Wire runtime."
    }
}
